const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  function eeEvaluate(obj) {
    return new Promise((resolve, reject) => obj.evaluate(resolve, reject));
  }

  // 1. Geometry & Time Definitions
  const rc = ee.Geometry.Point([-78.83, -33.64]).buffer(8000);     // Robinson Crusoe Island (approx)
  const sc = ee.Geometry.Point([-78.82, -33.68]).buffer(1200);     // Santa Clara Island (approx)
  const bounds = rc.union(sc);
  const dateOpts = [
    {start: '2018-11-01', end: '2018-11-30', label: 'Nov2018'},
    {start: '2018-10-15', end: '2018-12-15', label: '±45d'}
  ];
  const scale = 1000;

  // Land mask (avoid ocean influence)
  const waterOcc = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
  const landMask = waterOcc.lt(50); // likely land if water occurrence < 50%

  // S2 masking and NDVI
  function maskS2(img) {
    const qa60 = img.select('QA60');
    const cloud = qa60.bitwiseAnd(1 << 10).eq(0);
    const cirrus = qa60.bitwiseAnd(1 << 11).eq(0);
    const scl = img.select('SCL');
    const sclKeep = scl.neq(0).and(scl.neq(1)) // no data/defective
                   .and(scl.neq(3))            // cloud shadow
                   .and(scl.neq(8))            // cloud medium prob
                   .and(scl.neq(9))            // cloud high prob
                   .and(scl.neq(10))           // thin cirrus
                   .and(scl.neq(11))           // snow/ice
                   .and(scl.neq(6));           // water
    const m = cloud.and(cirrus).and(sclKeep);
    return img.updateMask(m);
  }
  function s2Ndvi(img) {
    return img.normalizedDifference(['B8','B4']).rename('NDVI');
  }

  // Landsat 8 masking and NDVI
  function maskL8(img) {
    const qa = img.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 3).eq(0);
    const cloudShadow = qa.bitwiseAnd(1 << 4).eq(0);
    const cirrus = qa.bitwiseAnd(1 << 2).eq(0);
    const snow = qa.bitwiseAnd(1 << 5).eq(0);
    return img.updateMask(cloud.and(cloudShadow).and(cirrus).and(snow));
  }
  function l8Ndvi(img) {
    const nir = img.select('SR_B5').multiply(0.0000275).add(-0.2);
    const red = img.select('SR_B4').multiply(0.0000275).add(-0.2);
    return nir.subtract(red).divide(nir.add(red)).rename('NDVI');
  }

  async function buildComposite() {
    // Try Sentinel-2 SR
    for (const d of dateOpts) {
      let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(d.start, d.end)
        .filterBounds(bounds)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
      const s = await eeEvaluate(col.size());
      if (s > 0) {
        const ndviMed = col.map(maskS2).map(s2Ndvi).median().updateMask(landMask).select('NDVI');
        return {img: ndviMed, count: s, dataset: 'S2_SR', dateLabel: d.label};
      }
    }
    // Fallback: Landsat 8 SR
    for (const d of dateOpts) {
      let col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterDate(d.start, d.end)
        .filterBounds(bounds);
      const s = await eeEvaluate(col.size());
      if (s > 0) {
        const ndviMed = col.map(maskL8).map(l8Ndvi).median().updateMask(landMask).select('NDVI');
        return {img: ndviMed, count: s, dataset: 'L8_SR', dateLabel: d.label};
      }
    }
    return null;
  }

  async function regionStats(img, geom) {
    const validCount = await eeEvaluate(img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI'));
    const totalCount = await eeEvaluate(ee.Image.constant(1).rename('one').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('one'));
    const meanNdvi = await eeEvaluate(img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI'));
    return {valid: validCount || 0, total: totalCount || 0, mean: meanNdvi};
  }

  try {
    const comp = await buildComposite();
    if (!comp) {
      console.log('No images found for both primary and fallback.');
      console.log('C1');
      return;
    }
    console.log(`Using ${comp.dataset} (${comp.dateLabel}) - Images: ${comp.count}`);

    const rcStats = await regionStats(comp.img, rc);
    const scStats = await regionStats(comp.img, sc);

    // Check C2: No valid pixels
    if ((rcStats.valid === 0) || (scStats.valid === 0)) {
      console.log(`RC Pixels: ${rcStats.valid}/${rcStats.total}, SC Pixels: ${scStats.valid}/${scStats.total}`);
      console.log('C2');
      return;
    }

    // Validate NDVI values
    function invalidNdvi(v) {
      return (v === null || v === undefined || isNaN(v) || v < -1.0 || v > 1.0);
    }
    if (invalidNdvi(rcStats.mean) || invalidNdvi(scStats.mean)) {
      console.log(`NDVI invalid - RC: ${rcStats.mean}, SC: ${scStats.mean}`);
      console.log('C3');
      return;
    }

    const rcMaskPct = rcStats.total > 0 ? (100 * (1 - rcStats.valid / rcStats.total)) : null;
    const scMaskPct = scStats.total > 0 ? (100 * (1 - scStats.valid / scStats.total)) : null;

    console.log(`RC - Valid: ${rcStats.valid}/${rcStats.total} (mask ${rcMaskPct !== null ? rcMaskPct.toFixed(1) : 'NA'}%), NDVI: ${rcStats.mean.toFixed(3)}`);
    console.log(`SC - Valid: ${scStats.valid}/${scStats.total} (mask ${scMaskPct !== null ? scMaskPct.toFixed(1) : 'NA'}%), NDVI: ${scStats.mean.toFixed(3)}`);

    // Final Answer
    const answer = rcStats.mean > scStats.mean ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err.message || err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
